INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427410, 16645, 'France 24', 'en', 'Norway mourns King Harald as Haakon prepares to take the throne', 'https://www.france24.com/en/norway-mourns-king-harald-as-haakon-prepares-to-take-the-throne', 'Norway is mourning King Harald V after the country''s longest-serving monarch died at the age of 89, with tributes pouring in from across Europe. His death paves the way for Crown Prince Haakon to become king, as the royal family faces renewed scrutiny over Crown Princess Mette-Marit''s reported past ties to Jeffrey Epstein and the conviction of her son for rape.', 'https://s.france24.com/media/display/d51c7b0a-a2ac-11f1-b15b-005056a97e36/w:1024/p:16x9/AP23128282047679.jpg', '2026-08-28T16:31:12+00:00', '2026-08-29T00:03:43.306068'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
