INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (428525, 16645, 'TIME', 'en', 'King Harald V of Norway Has Died After 35 Years On the Throne. Meet His Successor, Haakon', 'https://time.com/article/2026/08/28/king-harald-v-norway-dies-son-successor-haakon-family-controversy', 'King Harald V of Norway, Europe’s oldest monarch, died Friday at the age of 89. His son, the newly-proclaimed King Haakon VIII, has inherited the Norwegian throne. Here''s what to know about the new monarch, his family controversies, and more.', 'https://static.time.com/v3/assets/bltea6093859af6183b/blt4bb42926d6c88dca/6a91c07bf92b6bd79fa183b6/GettyImages-2276655892.jpg?branch=production', '2026-08-28T17:13:31+00:00', '2026-08-29T00:06:23.738356'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (428717, 16645, 'ABC Australia', 'en', 'Norway''s crown prince becomes King Haakon after father''s death', 'https://www.abc.net.au/news/2026-08-29/harald-death-sees-norway-crown-prince-becomes-king-haakon-viii/107093150', 'Crown Prince Haakon is the new king of Norway after the death of his father, Harald V, at the age of 89, on Friday, tasked with the challenge of rebuilding the reputation of the nation''s royal family in the wake of recent controversies.', 'https://live-production.wcms.abc-cdn.net.au/1d4e0a02771279851d4d85644f9174e7?impolicy=wcms_crop_resize&cropH=2620&cropW=4658&xPos=0&yPos=203&width=862&height=485', '2026-08-28T21:22:43+00:00', '2026-08-29T00:06:51.562680'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
