INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427878, 16657, 'The Economic Times', 'en', 'Sebi bars Trafiksol ITS, promoters for 1 year for misleading IPO disclosures', 'https://economictimes.indiatimes.com/markets/stocks/news/sebi-bars-trafiksol-its-promoters-for-1-year-for-misleading-ipo-disclosures/articleshow/133594730.cms', 'Sebi has banned Trafiksol and its promoters from the securities market for one year. Monetary penalties were also imposed on the company and its two promoters. The regulator found misleading financial disclosures and inflated revenue figures in the company''s IPO documents. Sebi also noted concealment of material facts and submission of false information regarding Oasis Corpcare. The IPO was unwound after Sebi directed Trafiksol to refund investors and cancel shares.', 'https://img.etimg.com/photo/msid-133594730,imgsize-78988.cms', '2026-08-28T15:28:57+00:00', '2026-08-29T00:04:38.942402'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
