INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427880, 16659, 'The Economic Times', 'en', 'Purple Style raises Rs 306 crore from anchor investors ahead of IPO; Morgan Stanley, BofA among buyers', 'https://economictimes.indiatimes.com/markets/ipos/fpos/purple-style-raises-rs-306-crore-from-anchor-investors-ahead-of-ipo-morgan-stanley-bofa-among-buyers/articleshow/133594672.cms', 'Purple Style Labs secured Rs 306 crore from anchor investors before its upcoming IPO. The company will open its initial public offering for subscription on Monday, August 31. This luxury fashion platform operates under Pernia''s Pop-Up Shop, offering curated designer products. It sources items from 1,109 active designer brands, focusing on wedding and occasion wear. Purple Style Labs utilizes an omni-channel model with 14 global experience centers.', 'https://img.etimg.com/photo/msid-133594672,imgsize-163898.cms', '2026-08-28T15:16:01+00:00', '2026-08-29T00:04:38.977444'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
