INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427871, 16661, 'The Economic Times', 'en', 'US green card queue stretches to 179 years', 'https://economictimes.indiatimes.com/nri/migrate/nearly-1-million-indians-stuck-in-us-green-card-queuesome-may-wait-179-years/articleshow/133586596.cms', 'Nearly one million Indians are waiting for US employment-based green cards, accounting for 79% of the estimated 1.26 million people in the backlog, according to a National Foundation for American Policy (NFAP) analysis.An Indian professional whose labour certification application or employment-based immigrant petition was filed in January 2026 or later could face a potential wait of 179 years in the EB-2 category and 38 years in EB-3, the analysis said. The potential wait in EB-1 is estimated at four to five years.The estimates do not include additional government processing time.Also Read| Tr', '', '2026-08-28T07:50:55+00:00', '2026-08-29T00:04:37.284049'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
